// Exports the icons listed in icons.json from the locally installed Nucleo app
// into src/icons/nucleo.ts (inline, theme-able SVG bodies).
//
// Requires the Nucleo desktop app with a license; the generated file is part of
// the app and must not be extracted or redistributed as an icon set.
//   node --no-warnings scripts/icons/export.mjs
import { DatabaseSync } from "node:sqlite";
import { copyFileSync, existsSync, readFileSync, writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { tmpdir } from "node:os";

const here = dirname(fileURLToPath(import.meta.url));
const appData = process.env.APPDATA ?? "";
let dataDir = join(appData, "Nucleo", "icons");
const dataPathFile = join(appData, "Nucleo", "storage", "dataPath.json");
if (existsSync(dataPathFile)) {
  try {
    const p = JSON.parse(readFileSync(dataPathFile, "utf8"));
    if (typeof p === "string" && p) dataDir = p;
    else if (p?.dataPath) dataDir = p.dataPath;
  } catch {}
}
const dbCopy = join(tmpdir(), "highbazar-nucleo.sqlite3");
copyFileSync(join(dataDir, "data.sqlite3"), dbCopy);
const db = new DatabaseSync(dbCopy, { readOnly: true });
const row = db.prepare("select id, name, set_id from icons where id = ?");

const manifest = JSON.parse(readFileSync(join(here, "icons.json"), "utf8"));
const out = [];
for (const [alias, id] of Object.entries(manifest)) {
  if (alias.startsWith("_")) continue;
  const r = row.get(id);
  if (!r) throw new Error(`${alias}: icon ${id} not found`);
  const raw = readFileSync(join(dataDir, "sets", String(r.set_id), `${id}.svg`), "utf8");
  const viewBox = raw.match(/viewBox="([^"]+)"/)?.[1] ?? "0 0 24 24";
  let body = raw
    .replace(/^[\s\S]*?<svg[^>]*>/, "")
    .replace(/<\/svg>\s*$/, "")
    .replace(/<g class="nc-icon-wrapper"[^>]*>/, "")
    .replace(/<\/g>\s*$/, "");
  // Secondary color parts get a class; colors become currentColor.
  body = body
    .replace(/<(\w+)([^>]*?)data-color="color-2"([^>]*)>/g, '<$1 class="nc-c2"$2$3>')
    .replace(/\s(fill|stroke)="(?!none)[^"]*"/g, ' $1="currentColor"')
    .replace(/\sdata-(cap|color|stroke)="[^"]*"/g, "")
    .replace(/>\s+</g, "><")
    .replace(/\s{2,}/g, " ")
    .trim();
  out.push(`  ${alias}: [${JSON.stringify(viewBox)}, ${JSON.stringify(body)}], // ${r.name} (#${id})`);
}

const file = `// Generated by scripts/icons/export.mjs from the Nucleo icon library (nucleoapp.com).
// Nucleo icons are licensed to the HighBazar author and are NOT covered by the MIT license
// of this project: they may be used as part of HighBazar, but not extracted or redistributed.
/* eslint-disable */
export const nucleo: Record<string, [string, string]> = {
${out.join("\n")}
};
`;
writeFileSync(join(here, "..", "..", "src", "icons", "nucleo.ts"), file);
console.log(`exported ${out.length} icons`);
